import { DataGrid, type DataGridColumn, type DataGridRow } from '@netscript/fresh-ui';

interface Invoice {
  id: string;
  customer: string;
  total: number;
}

const columns: DataGridColumn<Invoice>[] = [
  { key: 'customer', header: 'Customer', width: '2fr', cell: 'strong' },
  { key: 'total', header: 'Total', cell: 'num', render: (row) => `$${row.total.toFixed(2)}` },
];

const rows: DataGridRow<Invoice>[] = [
  { id: 'inv-1', data: { id: 'inv-1', customer: 'Acme', total: 420 }, href: '/invoices/inv-1' },
  {
    id: 'inv-2',
    data: { id: 'inv-2', customer: 'Globex', total: 130 },
    selected: true,
    href: '/invoices/inv-2',
  },
];

export function InvoiceGrid() {
  return <DataGrid label='Invoices' columns={columns} rows={rows} />;
}

import { Dropzone, type DropzoneIngestDetails } from '@app/components/ui/dropzone.tsx';

export function AvatarUpload() {
  function handleFiles(files: readonly File[], details: DropzoneIngestDetails) {
    console.log(`Accepted ${files.length} file(s) via ${details.source}`);
    for (const rejected of details.rejectedFiles) {
      console.warn(`Rejected ${rejected.file.name}: ${rejected.reason}`);
    }
  }

  return (
    <Dropzone
      label='Drop images or click to upload'
      hint='PNG or JPG, up to 5 MB'
      accept='image/png,image/jpeg'
      multiple
      onFiles={handleFiles}
    />
  );
}

// apps/dashboard/lib/example-service.ts
import { createServiceClient } from '@netscript/sdk/client';
import { createQueryFactories } from '@netscript/sdk/query';
import { bridgeInvalidation } from '@netscript/sdk/query-client';
import { UsersContractV1 } from '@plugin-smoke/contracts';

export const exampleServiceName = 'users';
export const exampleServiceClient = createServiceClient<typeof UsersContractV1>({
  contract: UsersContractV1,
  serviceName: exampleServiceName,
  routerName: 'users',
});

// queryOptions / mutationOptions derived straight from the contract.
export const exampleServiceQueries = createQueryFactories({
  service: { contract: UsersContractV1, client: exampleServiceClient },
}).service;

// definePage() declares a typed page: route + server-loaded layers + telemetry.
import { appRoutes } from '@app/router.ts';
import { definePage } from '@app/utils.ts';
import { ServiceExampleLabPanel } from './(_components)/lab-panel.tsx';
import { loadServiceShowcaseData } from './(_shared)/service-showcase.ts';

export const serviceExamplePage = definePage()
  .withRoute(appRoutes.serviceExample)
  .withPolicy('balanced')
  .withTelemetry({ enabled: true, spanName: 'scaffold.examples.users' })
  .withMeta(() => ({ title: 'users example', description: 'Backed by the users service.' }))
  .withLayer('lab', ServiceExampleLabPanel, { loader: loadServiceShowcaseData })
  .build();

export const { default: page } = serviceExamplePage;
export { page as default };

import { renderUiPayload, RenderUiSurface } from '@netscript/fresh-ui/ai/render-ui';

const payload = {
  component: 'section',
  title: 'System Performance',
  props: {
    children: [
      {
        type: 'grid',
        props: {
          children: [
            {
              type: 'metric',
              props: { label: 'P99 Latency', value: '24 ms', detail: 'healthy' },
            },
            {
              type: 'metric',
              props: { label: 'Error Rate', value: '0.01%', detail: 'normal' },
            },
          ],
        },
      },
      {
        type: 'table',
        title: 'Active Services',
        props: {
          columns: [
            { key: 'name', header: 'Service' },
            { key: 'status', header: 'Status' },
          ],
          rows: [
            { name: 'auth-service', status: 'healthy' },
            { name: 'payment-gateway', status: 'healthy' },
          ],
        },
      },
    ],
  },
};

export function PerformanceWidget() {
  return <RenderUiSurface payload={payload} maxDepth={6} />;
}
